import{_ as e,o as a,c as d,ag as r}from"./chunks/framework.DaCm-iTo.js";const m=JSON.parse('{"title":"EmakiForge","description":"","frontmatter":{},"headers":[],"relativePath":"modules/forge/index.md","filePath":"modules/forge/index.md","lastUpdated":null}'),o={name:"modules/forge/index.md"};function i(s,t,l,n,c,h){return a(),d("div",null,[...t[0]||(t[0]=[r(`<h1 id="emakiforge" tabindex="-1">EmakiForge <a class="header-anchor" href="#emakiforge" aria-label="Permalink to &quot;EmakiForge&quot;">​</a></h1><p>EmakiForge 负责锻造流程：玩家放入目标装备、图纸和材料后，模块检查配方、容量和条件，再改造目标装备或生成新装备。品质、材料贡献和结果展示都在这里配置。</p><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>值</th></tr></thead><tbody><tr><td>模块版本</td><td><code>4.6.4</code></td></tr><tr><td>主命令</td><td><code>/emakiforge</code></td></tr><tr><td>别名</td><td><code>/eforge</code>、<code>/ef</code></td></tr><tr><td>硬依赖</td><td>EmakiCoreLib</td></tr><tr><td>软依赖</td><td>EmakiAttribute、EmakiItem、PlaceholderAPI</td></tr><tr><td>主要权限</td><td><code>emakiforge.use</code>、<code>emakiforge.book</code>、<code>emakiforge.reload</code>、<code>emakiforge.debug</code>、<code>emakiforge.admin</code></td></tr></tbody></table><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><table tabindex="0"><thead><tr><th>概念</th><th>说明</th></tr></thead><tbody><tr><td>图纸</td><td>控制玩家是否能执行某个锻造配方。</td></tr><tr><td>材料</td><td>玩家投入的资源，可以影响成功、品质或最终属性。</td></tr><tr><td>配方</td><td>定义输入要求、容量、条件、结果和动作。</td></tr><tr><td>容量</td><td>限制可投入材料的 <code>capacity_cost</code> 总和。</td></tr><tr><td>品质</td><td>锻造结果的确定性加权等级，可配保底。</td></tr><tr><td>配方书</td><td>玩家查看可用配方的 GUI。</td></tr></tbody></table><h2 id="默认配置目录" tabindex="-1">默认配置目录 <a class="header-anchor" href="#默认配置目录" aria-label="Permalink to &quot;默认配置目录&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plugins/EmakiForge/</span></span>
<span class="line"><span>├── config.yml</span></span>
<span class="line"><span>├── recipes/</span></span>
<span class="line"><span>│   └── example_recipe.yml</span></span>
<span class="line"><span>├── gui/</span></span>
<span class="line"><span>│   ├── forge_gui.yml</span></span>
<span class="line"><span>│   └── recipe_book.yml</span></span>
<span class="line"><span>├── lang/</span></span>
<span class="line"><span>│   ├── zh_CN.yml</span></span>
<span class="line"><span>│   └── en_US.yml</span></span>
<span class="line"><span>└── data/</span></span></code></pre></div><p>先改 <code>recipes/</code>。它决定锻造玩法的输入、容量、条件、结果和动作。<code>data/</code> 由 <code>PlayerDataStore</code> 维护，按玩家 UUID 存放 <code>&lt;uuid&gt;.yml</code> 锻造计数与保底计数。</p><h2 id="功能页面" tabindex="-1">功能页面 <a class="header-anchor" href="#功能页面" aria-label="Permalink to &quot;功能页面&quot;">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>内容</th></tr></thead><tbody><tr><td><a href="./commands.html">命令与权限</a></td><td>锻造、配方书、重载、列表和调试命令。</td></tr><tr><td><a href="./recipes.html">配方系统</a></td><td>输入、图纸、结果、动作和配方匹配。</td></tr><tr><td><a href="./materials.html">材料系统</a></td><td>材料贡献、容量、品质修正和效果写入。</td></tr><tr><td><a href="./quality.html">品质系统</a></td><td>品质池、保底、物品元数据和确定性算法。</td></tr><tr><td><a href="./history.html">锻造历史记录</a></td><td>玩家锻造数据、自动保存和异常排查。</td></tr><tr><td><a href="./gui.html">GUI</a></td><td>锻造界面与配方书模板。</td></tr><tr><td><a href="./audit.html">审计</a></td><td>结果物品的锻造审计数据与材料签名。</td></tr><tr><td><a href="./placeholders.html">占位符</a></td><td>PlaceholderAPI 输出。</td></tr><tr><td><a href="./corelib-actions.html">CoreLib 动作</a></td><td>Forge 注册的刷新动作。</td></tr><tr><td><a href="./api.html">API 接入</a></td><td><code>EmakiForgeApi</code> 静态门面。</td></tr><tr><td><a href="./events.html">事件 API</a></td><td><code>ForgeStartEvent</code>、<code>ForgeCompletedEvent</code>。</td></tr></tbody></table><h2 id="典型锻造流程" tabindex="-1">典型锻造流程 <a class="header-anchor" href="#典型锻造流程" aria-label="Permalink to &quot;典型锻造流程&quot;">​</a></h2><ol><li>玩家用 <code>/ef forge</code> 打开锻造 GUI。</li><li>在图纸槽放入图纸，Forge 按图纸物品源自动匹配配方。</li><li>在必需材料槽和可选材料槽放入材料。</li><li>模块检查配方、条件、容量和材料数量。</li><li>玩家点击确认槽，触发 <code>actions.pre</code>。</li><li>按玩家 + 配方 + 材料指纹计算确定性品质与保底。</li><li>生成 <code>result.success.outputs</code> 中的主产物，并附加 forge layer 快照。</li><li>依次执行 <code>result.success.actions</code> → <code>actions.success</code> → 品质动作；失败时执行 <code>actions.failure</code>。</li><li>CoreLib 物品装配服务重建物品展示。</li><li>安装 EmakiAttribute 时，材料的 <code>ea_attribute</code> 效果写入结构化 PDC 属性层。</li></ol><h2 id="与-attribute-的关系" tabindex="-1">与 Attribute 的关系 <a class="header-anchor" href="#与-attribute-的关系" aria-label="Permalink to &quot;与 Attribute 的关系&quot;">​</a></h2><p>Forge 可以不安装 Attribute 运行基础锻造功能。材料的 <code>ea_attribute</code> 效果需要 EmakiAttribute 才会生效：此时属性通过 EmakiAttribute 的权威 API 写入结构化 PDC layer，参与真实战斗计算，而不是只显示在 Lore 中。</p><p>EmakiAttribute 未安装时，Forge 走 no-op 路径：锻造照常完成，只是不写入属性 payload，不会报错或中断流程。</p>`,16)])])}const u=e(o,[["render",i]]);export{m as __pageData,u as default};
